        # handle floats robustly: count primes p with p < n
        import math
        if isinstance(n, float):
            if math.isnan(n) or math.isinf(n):
                return 0 if n != float('inf') else 0
            if n <= 2:
                return 0
            ni = int(math.floor(n))
            # primes p < n  <=> p <= floor(n) if n not integer, else p <= n-1
            if float(ni) == n:
                n = ni
            else:
                n = ni + 1
        if n <= 2:
            return 0
        n = int(n)
        if n <= 2:
            return 0
        sieve = bytearray(b'\x01') * n
        sieve[0:2] = b'\x00\x00'
        sq = int(n**0.5) + 1
        for i in range(2, sq):
            if sieve[i]:
                sieve[i*i:n:i] = bytes(len(range(i*i, n, i)))
        return int(sum(sieve))
    except TypeError:
        return 0

