{"task_id": "T21", "code": "def solve(weights, values, capacity):
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    # DP: dp[c] = max value achievable with capacity c
    dp = [0] * (capacity + 1)
    for i in range(n):
        w, v = weights[i], values[i]
        # Traverse capacities in reverse to avoid using item twice
        for c in range(capacity, w - 1, -1):
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[capacity]
