def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    if all(len(row) == n for row in matrix) is False:
        return 0
    # Use fraction-free Gaussian elimination to avoid float issues
    m = [row[:] for row in matrix]
    det = 1
    sign = 1
    for i in range(n):
        pivot = -1
        for k in range(i, n):
            if m[k][i] != 0:
                pivot = k
                break
        if pivot == -1:
            return 0
        if pivot != i:
            m[i], m[pivot] = m[pivot], m[i]
            sign = -sign
        # Eliminate below, using integer arithmetic (bareiss algorithm)
        for k in range(i + 1, n):
            for j in range(i + 1, n):
                m[k][j] = m[i][i] * m[k][j] - m[k][i] * m[i][j]
                if i > 0:
                    m[k][j] //= m[i-1][i-1] if m[i-1][i-1] != 0 else 1
            m[k][i] = 0
        if m[i][i] == 0:
            return 0
    return sign * m[n-1][n-1]

