def solve(s):
    if not s:
        return ''
    n = len(s)
    start, length = 0, 1
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l+1, r-l-1
    for i in range(n):
        l1, len1 = expand(i, i)
        l2, len2 = expand(i, i+1)
        if len1 > length:
            start, length = l1, len1
        if len2 > length:
            start, length = l2, len2
    return s[start:start+length]
